"""Native money/stat effects, real local police cases and saved bounty contracts."""
import struct
from native_hooks import h
from life_rework.systems import stat
from playable_repair.fight_actions import blueprint_prefix
from life_repair.bridges import allocate
from era_life1121.catalog import FOODS

def bits(reg,value):
 n=struct.unpack('<Q',struct.pack('<d',value))[0]
 return f'movz {reg},#{n&65535}\nmovk {reg},#{n>>16&65535},lsl #16\nmovk {reg},#{n>>32&65535},lsl #32\nmovk {reg},#{n>>48},lsl #48\n'

def install(b,year,factor):
 # GetOpenCrimesInPlaceOfResidence returns the game's actual ArrayList.
 # Never manufacture convictions or clear it to make a status screen look good.
 s='str xzr,[sp]\n'+h.load_game()+'\nldr x0,[x8,#0x30]\ncbz x0,finish\nmov x1,xzr\nbl 0x2a88f34\nstr x0,[sp]\nb finish'
 cases=b.routine('era1121_actual_open_cases',s)
 s='str xzr,[sp]\n'+h.load_game()+'\nldr x8,[x8,#0x20]\ncbz x8,finish\nldr x0,[x8,#0xe8]\nstr x0,[sp]\nb finish'
 bank=b.routine('era1121_actual_bank',s)
 s='str xzr,[sp]\n'+h.load_game()+'\nldr x0,[x8,#0x28]\ncbz x0,finish\nldr w9,[x0,#0x20]\ncmp w9,#18\nb.lt finish\n'+f'bl {year:#x}\ncmp w0,#1800\nb.lt finish\ncmp w0,#1900\nb.ge finish\n'+h.load_occupation()+'\nldr w9,[x8,#0x10]\ncmp w9,#2\nb.ne finish\nldr x8,[x8,#0x40]\ncbz x8,finish\nldr x8,[x8,#0x18]\ncbz x8,finish\n'+h.compare_key('Bounty Hunter','bounty_job1121','finish')+'\nbounty_job1121:\n'+h.load_game()+'\nldr x0,[x8,#0x28]\nmov x1,xzr\nbl 0x2c38288\ncbz x0,finish\nmov x1,xzr\nbl 0x2a27280\ncbz x0,finish\nldr x8,[x0,#0x10]\ncbz x8,finish\n'+h.compare_key('United States','bounty_us1121','bounty_alias1121')+'\nbounty_alias1121:\n'+h.compare_key('United States of America','bounty_us1121','finish')+'\nbounty_us1121:\n'+f'bl {cases:#x}\ncbz x0,bounty_permit1121\nldr w9,[x0,#0x18]\ncbnz w9,finish\nbounty_permit1121:\nmov w9,#1\nstr x9,[sp]\nb finish'
 eligible=b.routine('era1121_bounty_eligible',s)
 # Refresh amounts for visible food labels. snprintf sees integer cents,
 # avoiding locale-dependent decimal parsing and whole-dollar truncation.
 price='mov w25,w0\n'+f'bl {factor:#x}\numull x9,w25,w0\nmov x10,#1000\nudiv x9,x9,x10\nmov x10,#1\ncmp x9,#1\ncsel x9,x9,x10,ge\nstr x9,[sp]\nb finish'
 cost=b.routine('era1121_food_cost_cents',price)
 fmt='mov w25,w0\nmov w9,#100\nudiv w3,w25,w9\nmsub w4,w3,w9,w25\nadd x0,sp,#0x80\nmov w1,#32\n'+f'adr x2,{b.literal("%u.%02u"):#x}\nbl {b.snprintf:#x}\nadd x0,sp,#0x80\nbl {h.NEW_STRING:#x}\nstr x0,[sp]\nb finish'
 moneytext=b.routine('era1121_price_text',fmt)
 s=b.ctx('life_rework')+b.set('WantedCases1121',0)+b.set('WantedRun1121',0)+b.set('NativeBounty1121',0)+f'bl {cases:#x}\ncbz x0,no_cases1121\nldr w25,[x0,#0x18]\n'+b.put('WantedCases1121','w25')+'cbz w25,no_cases1121\n'+b.text('WantedText1121','There are <GFC.life_rework.WantedCases1121> open cases in your current country. Surrender opens the original arrest and court process; it does not erase the charges. Crew attention: <GFC.life_rework.HeistHeat1106>.')+'b wanted_run1121\nno_cases1121:\n'+b.text('WantedText1121','No open police cases are recorded in your current country. Crew attention: <GFC.life_rework.HeistHeat1106>. Attention is not itself a conviction.')+'wanted_run1121:\n'+h.load_game()+'\nldr x0,[x8,#0x30]\ncbz x0,wanted_job1121\nmov x1,xzr\nbl 0x2a89368\ncbz w0,wanted_job1121\n'+b.set('WantedRun1121',1)+b.text('WantedText1121','You are wanted after a prison escape in your current country. Surrender opens the original arrest process. Open cases: <GFC.life_rework.WantedCases1121>.')+'wanted_job1121:\n'+f'bl {eligible:#x}\nmov w25,w0\n'+b.put('NativeBounty1121','w25')+'cbnz w25,board_ready1121\n'+b.text('BountyText1121','You need to work as a Bounty Hunter in the United States during 1800–1899, be at least 18, and have no open local police cases. Apply through the normal Jobs menu.')+'b food_labels1121\nboard_ready1121:\n'+b.get('BountyStage1121')+'cbnz w24,food_labels1121\n'+b.text('BountyText1121','The sheriff has posted a reward for an escaped suspect. Read a notice, gather two independent leads and arrange the arrest. One contract can be finished each year.')+'food_labels1121:\n'
 for i,(_,_,base)in enumerate(FOODS):s+=f'mov w0,#{base}\nbl {cost:#x}\nbl {moneytext:#x}\nmov x22,x0\n'+b.textptr('FoodPrice1121_'+str(i))
 sync=b.routine('era1121_sync_law_and_market',s+'b finish')
 # Bound checked native transaction: exact double balance, integer cents.
 s='mov w19,w0\n'+b.ctx('life_rework')+b.text('MarketMessage1121','You could not complete that purchase. Your money was kept.')+h.load_game()+'\nldr x8,[x8,#0x28]\ncbz x8,finish\nldr w9,[x8,#0x20]\ncmp w9,#8\nb.lt food_young1121\n'+b.get('FoodAge1121')+'cmp w24,w23\nb.eq food_quota1121\n'+b.put('FoodAge1121','w23')+b.set('FoodUses1121',0)+'food_quota1121:\n'+b.get('FoodUses1121')+'cmp w24,#3\nb.ge food_full1121\n'
 for i,(label,icon,base)in enumerate(FOODS):
  s+=f'cmp w19,#{980+i}\nb.ne food_next1121_{i}\nmov w0,#{base}\nbl {cost:#x}\nmov w25,w0\nbl {bank:#x}\ncbz x0,finish\nmov x27,x0\nldr d0,[x27,#0x10]\nucvtf d1,w25\n'+bits('x9',100.)+'fmov d2,x9\nfdiv d1,d1,d2\nfmul d0,d0,d2\n'+bits('x9',1e-7)+'fmov d3,x9\nfadd d0,d0,d3\nfcvtzs x9,d0\ncmp x9,x25\nb.lt food_funds1121\nldr d0,[x27,#0x10]\nfmin d1,d1,d0\nfneg d0,d1\nmov x0,x27\nmov x1,xzr\nbl 0x2a6eb5c\n'+b.inc('FoodUses1121')+b.text('MarketMessage1121',f'You bought {label.lower()} and shared a meal. The displayed price was deducted exactly; the meal helped your wellbeing.')+stat(b,0x2c46670,2)+stat(b,0x2c46584,1)+b.string(f'I bought {label.lower()} at the local market and had a meal.')+f'bl {b.journal55:#x}\nb finish\nfood_next1121_{i}:\n'
 s+='b finish\nfood_young1121:\n'+b.text('MarketMessage1121','You need to be eight to shop here. No money was spent.')+'b finish\nfood_full1121:\n'+b.text('MarketMessage1121','You have already bought three meals this year. No money was spent.')+'b finish\nfood_funds1121:\n'+b.text('MarketMessage1121','You cannot afford this serving. Your money was kept.')+'b finish'
 food=b.routine('era1121_buy_food',s)
 bounty=contracts(b,eligible,factor,bank)
 # Existing action schema's 1000 maximum is respected, other commands pass on.
 r=b.resolved('life_rework_native_action');s='cmp w0,#960\nb.lt finish\ncmp w0,#987\nb.gt finish\nmov w19,w0\ncmp w19,#980\nb.ge action_food1121\ncmp w19,#960\nb.eq action_sync1121\ncmp w19,#967\nb.gt finish\n'+f'bl {bounty:#x}\nb return_custom\naction_sync1121:\nbl {sync:#x}\nb return_custom\naction_food1121:\nbl {food:#x}\nb return_custom'
 b.chain('era1121_native_market_and_bounty_commands',r['name'],s,ret=True)
 # The actual native arrest receives the actual original list of charges.
 s=blueprint_prefix(b,'wanted1121')+'ldr x8,[x19,#0x18]\ncbz x8,finish\n'+h.compare_key('WantedSurrender1121','surrender1121','finish')+'\nsurrender1121:\n'+b.ctx('life_rework')+'cmp w23,#8\nb.lt finish\n'+f'bl {cases:#x}\ncbz x0,finish\nldr w9,[x0,#0x18]\ncbz w9,finish\nmov x27,x0\n'+allocate(b,'ScenarioCrimeArrest')+'mov x1,x27\nmov x2,xzr\nbl 0x35f3378\nstr x25,[sp]\nb return_custom'
 b.chain('era1121_surrender_original_arrest','repair_original_school_combat_and_minefield',s,ret=True)

def contracts(b,eligible,factor,bank):
 s='mov w19,w0\n'+b.ctx('life_rework')+f'bl {eligible:#x}\ncbz w0,bounty_denied1121\ncmp w19,#961\nb.eq bounty_accept1121\n'+b.get('BountyAge1121')+'cmp w24,w23\nb.ne bounty_expired1121\n'+b.get('BountyStage1121','w25')+'cbz w25,bounty_expired1121\n'
 for n,label in [(962,'witness'),(963,'trail'),(964,'approach'),(965,'leave'),(966,'backup'),(967,'alone')]:s+=f'cmp w19,#{n}\nb.eq bounty_{label}1121\n'
 s+='b finish\nbounty_accept1121:\n'+b.get('BountyAge1121')+'cmp w24,w23\nb.ge bounty_taken1121\n'+b.put('BountyAge1121','w23')+b.set('BountyStage1121',1)+b.set('BountyClue1121',0)+b.set('BountyAsked1121',0)+b.set('BountyTrail1121',0)+b.set('BountySuccess1121',0)+b.get('Roll','w25')+'add w25,w25,w23\nmov w9,#3\nudiv w10,w25,w9\nmsub w25,w10,w9,w25\nadd w25,w25,#1\n'+b.put('BountyCase1121','w25')+f'bl {factor:#x}\nmov w9,#20000\nmul w9,w9,w0\nmov w10,#1000\nudiv w25,w9,w10\n'+b.put('BountyReward1121','w25')+b.get('BountyCase1121','w25')
 for i,(name,charge,place)in enumerate([('Elias Bell','robbery','the abandoned mill'),('Clara Reed','horse theft','the northern stable'),('Jonah Pike','escape from custody','the riverside warehouse')],1):
  s+=f'cmp w25,#{i}\nb.ne bounty_notice_next1121_{i}\n'+b.text('BountyName1121',name)+b.text('BountyText1121',f'{name} is sought for {charge}. Last reported near {place}. Reward: <GFC.life_rework.BountyReward1121> in local currency, on lawful delivery to the sheriff. These are fictional game contracts. Ask witnesses and read the trail before approaching.')+f'b finish\nbounty_notice_next1121_{i}:\n'
 s+='b finish\nbounty_witness1121:\n'+b.get('BountyAsked1121')+'cbnz w24,bounty_repeated1121\n'+b.set('BountyAsked1121',1)+b.inc('BountyClue1121')+b.set('BountyStage1121',2)+b.text('BountyText1121','A witness confirms the suspect’s description and warns of a guarded back door. This lead is recorded. Check the trail for an independent confirmation.')+'b finish\nbounty_trail1121:\n'+b.get('BountyTrail1121')+'cbnz w24,bounty_repeated1121\n'+b.set('BountyTrail1121',1)+b.inc('BountyClue1121')+b.set('BountyStage1121',2)+b.text('BountyText1121','You follow fresh tracks to the hideout and identify a safe observation point. This lead is recorded. A witness can confirm who is inside.')+'b finish\nbounty_approach1121:\n'+b.get('BountyClue1121')+'cmp w24,#1\nb.lt bounty_need_lead1121\n'+b.set('BountyStage1121',3)+b.text('BountyText1121','You watch the hideout. The suspect is inside. Backup is safer, but the sheriff needs both leads to identify the suspect. A solo arrest carries an injury risk.')+'b finish\nbounty_backup1121:\ncmp w25,#3\nb.ne bounty_wrong_step1121\n'+b.get('BountyClue1121')+'cmp w24,#2\nb.lt bounty_no_backup1121\nb bounty_paid1121\nbounty_alone1121:\ncmp w25,#3\nb.ne bounty_wrong_step1121\n'+b.get('BountyClue1121')+'cmp w24,#2\nb.lt bounty_hurt1121\n'+b.get('Roll')+'cmp w24,#65\nb.ge bounty_hurt1121\nb bounty_paid1121\nbounty_paid1121:\n'+b.get('BountyReward1121','w25')+f'bl {bank:#x}\ncbz x0,finish\nscvtf d0,w25\nmov x1,xzr\nbl 0x2a6eb5c\n'+b.set('BountyStage1121',0)+b.set('BountySuccess1121',1)+b.text('BountyText1121','The suspect was delivered alive to the sheriff. Your <GFC.life_rework.BountyReward1121> reward was paid to your bank. The contract is closed; its reward cannot be claimed again.')+b.string('I completed a bounty contract and delivered the suspect alive to the sheriff.')+f'bl {b.journal55:#x}\nb finish\nbounty_hurt1121:\n'+b.set('BountyStage1121',0)+stat(b,0x2c46670,-12)+b.text('BountyText1121','The solo arrest failed. The suspect escaped and you were injured. No reward was paid. The sheriff closed this contract.')+b.string('I was injured during a failed bounty arrest. The suspect escaped and no reward was paid.')+f'bl {b.journal55:#x}\nb finish\nbounty_leave1121:\n'+b.set('BountyStage1121',0)+b.text('BountyText1121','You withdrew from this contract. No reward was paid. Another notice becomes available next year.')+'b finish\n'
 messages={'denied':'This contract requires your actual Bounty Hunter job, the United States in 1800–1899, adulthood and no open local charges. No reward or money changed.','expired':'This hunt is no longer active. Read the current board before starting another.','taken':'You have already accepted a contract this year. An active hunt stays in Current hunt; a closed contract cannot pay twice.','closed':'The arrest is already underway. Choose your approach at the hideout.','repeated':'You have already recorded this lead. Repeating it does not add another clue.','need_lead':'You have no confirmed lead. Speak to witnesses or follow the trail first.','wrong_step':'Reach the hideout before attempting the arrest. No reward was paid.','no_backup':'The sheriff needs both a witness statement and trail evidence. Gather the missing lead before requesting backup.'}
 for key,message in messages.items():s+='bounty_'+key+'1121:\n'+b.text('BountyText1121',message)+'b finish\n'
 return b.routine('era1121_bounty_contract',s)
